let toastTimer;

function t(key){return (translations[lang]&&translations[lang][key])||translations['en-GB'][key]||key;}
function displayPath(path=cwd){if(path==='/home/operator')return '~';if(path.startsWith('/home/operator/'))return '~'+path.slice('/home/operator'.length);return path;}
function applyLanguage(){document.documentElement.lang=lang==='zh-TW'?'zh-Hant':lang;document.querySelectorAll('[data-i18n]').forEach(el=>{el.textContent=t(el.dataset.i18n);});$('commandInput').placeholder=lang==='ja'?'コマンドを入力…':lang==='ko'?'명령 입력…':lang==='zh-TW'?'輸入命令…':'Enter a command…';updateView();}
function showToast(message){const toast=$('toast');toast.textContent=message;toast.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.classList.remove('show'),2600);}
function addTerminal(command,output='',isError=false){const box=$('terminalOutput');const line=document.createElement('div');line.className='terminal-line terminal-command';const prompt=document.createElement('span');prompt.className='prompt';prompt.textContent=`${displayPath()} $`;const cmd=document.createElement('span');cmd.textContent=command;line.append(prompt,cmd);box.append(line);if(output){const result=document.createElement('div');result.className='terminal-line terminal-result'+(isError?' terminal-error':'');result.textContent=output;box.append(result);}box.scrollTop=box.scrollHeight;}
function addEvent(message,level='INFO'){const row=document.createElement('div');row.className='event-row';const time=document.createElement('time');time.textContent=new Date().toLocaleTimeString(lang,{hour12:false});const tag=document.createElement('span');tag.className='event-level '+(level==='WARN'?'warn-level':'');tag.textContent=level;const text=document.createElement('span');text.textContent=message;row.append(time,tag,text);$('eventList').prepend(row);}
function absolutePath(input,base=cwd){if(!input||input==='.')return base;if(input==='-')return previousDir;let raw=input.replace(/^~/,'/home/operator');if(!raw.startsWith('/'))raw=base+'/'+raw;const stack=[];for(const piece of raw.split('/')){if(!piece||piece==='.')continue;if(piece==='..')stack.pop();else stack.push(piece);}return '/'+stack.join('/');}
