function words(line){const out=[];const re=/"([^"\\]*(?:\\.[^"\\]*)*)"|'([^']*)'|(\S+)/g;let m;while((m=re.exec(line)))out.push((m[1]??m[2]??m[3]).replace(/\\(["'\\])/g,'$1'));return out;}
