function completeCandidates(input){
  const match=input.match(/(?:^|\s)([^\s]*)$/),partial=match?.[1]??'',tokenStart=input.length-partial.length,parts=words(input.slice(0,tokenStart).trim()),first=parts[0]||'';
  const commands=['pwd','ls','ll','la','cd','cat','less','head','tail','grep','find','mkdir','touch','cp','mv','rm','rmdir','chmod','vi','vim','tree','echo','clear','history','help','kubectl','k','kg','kgp','kgn','docker','whoami','hostname','uname','ip','ping','route','nslookup','dig','ss','netstat','uptime','du','wc','sort','uniq','basename','dirname','df','free','ps','env','which','alias'];
  let candidates=[];
  if(!parts.length)candidates=commands.filter(x=>x.startsWith(partial));
  else if((first==='kubectl'||first==='k')&&parts[1]==='get'&&parts.length<=2)candidates=Object.keys(resourceAliases).filter(x=>x.startsWith(partial));
  else {
    const pathCommands=['cd','ls','cat','less','head','tail','grep','find','mkdir','touch','cp','mv','rm','rmdir','chmod','vi','vim'];
    const kubectlFile=(first==='kubectl'||first==='k')&&parts.includes('-f');
    const wantsPath=pathCommands.includes(first)||kubectlFile||(['kg','kgp','kgn'].includes(first))||(first==='docker'&&parts[1]==='logs');
    if(wantsPath){
      const query=partial,slash=query.lastIndexOf('/'),dirPart=slash>=0?query.slice(0,slash+1):'',namePart=slash>=0?query.slice(slash+1):query,dir=absolutePath(dirPart||'.');
      if(dirs.has(dir))candidates=directChildren(dir).map(([name,item])=>dirPart+name+(item.directory?'/':'')).filter(x=>x.replace(/\/$/,'').split('/').pop().startsWith(namePart));
      if(first==='docker'&&parts[1]==='logs')candidates=['amf','smf-voice','upf-data','upf-voice'].filter(x=>x.startsWith(partial));
    }
  }
  if(!candidates.length)return;
  let replacement;
  if(tabState.value===input&&tabState.matches.length){tabState.index=(tabState.index+1)%tabState.matches.length;replacement=tabState.matches[tabState.index];}
  else{tabState={value:input,matches:candidates,index:0};replacement=candidates.length===1?candidates[0]:commonPrefix(candidates);if(replacement===partial&&candidates.length>1){addTerminal('',candidates.join('   '));return;}}
  const isDir=dirs.has(absolutePath(replacement));$('commandInput').value=input.slice(0,tokenStart)+replacement+(candidates.length===1?(isDir?'/':' '):'');$('commandInput').setSelectionRange($('commandInput').value.length,$('commandInput').value.length);
}
function commonPrefix(values){let p=values[0]||'';for(const v of values.slice(1)){while(!v.startsWith(p)&&p)p=p.slice(0,-1);}return p;}
function submitCommand(line){const raw=line.trim();if(!raw)return;commandHistory.push(raw);historyIndex=commandHistory.length;addTerminal(raw);const result=runInput(raw);if(result.text)addTerminal('',result.text,result.error);$('commandInput').value='';$('commandInput').focus();tabState={value:'',matches:[],index:0};}

