  if(e.key==='Escape'){e.preventDefault();editorMode='NORMAL';$('editorMode').textContent=editorMode;return;}
  if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='s'){e.preventDefault();saveEditor(false);return;}
