  if(e.key==='ArrowUp'||e.key==='ArrowDown'){e.preventDefault();if(!commandHistory.length)return;historyIndex=Math.max(0,Math.min(commandHistory.length,historyIndex+(e.key==='ArrowUp'?-1:1)));e.currentTarget.value=commandHistory[historyIndex]||'';return;}
